"""Standalone benchmark replay with directed action certificates."""

import base64
import gzip
import json


def write_visualization(path, payload):
    packed = gzip.compress(
        json.dumps(payload, allow_nan=False, separators=(",", ":")).encode("utf-8"),
        mtime=0,
    )
    data = base64.b64encode(packed).decode("ascii")
    path.write_text(HTML.replace("__DATA__", data), encoding="utf-8")


HTML = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GP-Safety-Gym benchmark replay</title><style>
body{font:16px/1.55 system-ui,sans-serif;background:#f3f6fa;color:#17364a;max-width:1250px;margin:auto;padding:24px}h1{line-height:1.15}h2{font-size:1.1rem}.panel{background:white;border:1px solid #d5dfe8;border-radius:12px;padding:18px;margin:16px 0}.maps{display:grid;grid-template-columns:1fr 1fr;gap:18px}.controls{display:flex;gap:10px;flex-wrap:wrap;align-items:center}input{flex:1;min-width:160px}button,select{font:inherit;padding:6px 12px}svg,img{width:100%;height:auto}.metrics{display:flex;gap:22px;flex-wrap:wrap}.metrics strong{font-size:1.6rem;display:block}.muted{color:#536b7a}.note{border-left:4px solid #be8b37;padding-left:14px}.label{font-size:9px;text-anchor:middle;fill:#17364a}@media(max-width:750px){.maps{grid-template-columns:1fr}body{padding:12px}}
</style></head><body><h1>GP-Safety-Gym · headless benchmark</h1><p id="scope"></p><p class="note">This runs the discrete benchmark model and replays its saved decisions. The legacy Safety-Gym/MuJoCo Engine_GP has not been executed. Safety belongs to directed actions: altitude at source minus altitude at successor must meet the threshold. A reachable cell does not authorize every outgoing action.</p>
<div class="panel"><div class="controls"><button id="previous">Previous</button><button id="play">Play</button><button id="next">Next</button><input id="step" type="range" min="0" value="0" aria-label="Replay action"><strong id="stepLabel"></strong></div><p id="decision"></p><div class="metrics" id="metrics"></div></div>
<div class="maps"><div class="panel"><h2>Controller executable region</h2><p class="muted">Blue: reachable and returnable under accepted actions; yellow: optimistic only. Small blue arrows are certified directions. Hover for action names and GP estimates.</p><svg id="belief" role="img" aria-label="Executable region and directed action certificates"></svg></div><div class="panel"><h2>True benchmark field · evaluator only</h2><label>Field <select id="field"><option value="altitude">Altitude</option><option value="reward">Reward</option></select></label><p class="muted">Colors show field value, not a cell-level safety label. Hover for true safe outgoing actions. True maps never choose learner actions.</p><svg id="truth" role="img" aria-label="True benchmark field and complete replay prefix"></svg></div></div>
<div class="panel"><h2>Return and region growth</h2><svg id="growth" viewBox="0 0 760 200" role="img" aria-label="Discounted return and reachable fraction"></svg><p class="muted">Blue: discounted return divided by this run's maximum (display scale only). Purple: executable cells divided by all cells. These curves are explanatory; use the comparison report for raw return statistics.</p></div>
<div class="panel"><h2>Outcome and method</h2><p id="outcome"></p><p id="diagnostic"></p><p class="muted">Both GPs update from authorized noisy observations in both phases. SafeMDP remains an uncertainty sampler; the two-phase methods switch on their declared condition. Source defaults and deliberate changes are documented in docs/method.md. Finite experiments and practical confidence bands do not establish the paper's guarantees.</p></div>
<div class="panel"><h2>Optional exported overview</h2><img src="overview.png" hidden onload="this.hidden=false" alt="Exported 3D altitude surface with reward colors and simulated path"><p class="muted">If absent, create it using the documented plot command. This plot is an alternative visualization, not native MuJoCo rendering.</p></div>
<script id="data" type="application/octet-stream">__DATA__</script><script>
(async()=>{
if(typeof DecompressionStream==='undefined')throw new Error('Use a current browser with gzip DecompressionStream support.');
const encoded=document.getElementById('data').textContent.trim();
const bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));
const unpacked=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
const data=JSON.parse(unpacked),frames=data.frames,$=id=>document.getElementById(id),ns='http://www.w3.org/2000/svg';let timer=null;
const slider=$('step');slider.max=frames.length-1;
function node(tag,attrs={},text){const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,String(v));if(text!==undefined)e.textContent=text;return e;}
function draw(id,f,index,truth){const svg=$(id);svg.replaceChildren();const cell=32,pad=24,xy=(x,y)=>[pad+x*cell+15,pad+(data.cols-1-y)*cell+15];svg.setAttribute('viewBox',`0 0 ${data.rows*cell+pad*2} ${data.cols*cell+pad*2}`);const field=data[$('field').value||'altitude'],values=field.flat(),lo=Math.min(...values),hi=Math.max(...values);
for(let x=0;x<data.rows;x++){for(let y=0;y<data.cols;y++){const s=x*data.cols+y,[cx,cy]=xy(x,y);const fill=truth?`hsl(${35+100*(field[x][y]-lo)/(hi-lo||1)} 48% 75%)`:(f.pessimistic[x][y]?'#a7d6ee':f.optimistic[x][y]?'#ffe2a0':'#e3e8ed');const target=f.target&&f.target[0]===x&&f.target[1]===y;const r=node('rect',{x:cx-15,y:cy-15,width:30,height:30,rx:2,fill,stroke:!truth&&target?'#8951ae':'white','stroke-width':!truth&&target?3:1});
let text=`(${x}, ${y})`;if(truth){text+=` altitude ${data.altitude[x][y].toFixed(4)}, reward ${data.reward[x][y].toFixed(4)}`;const good=[];for(let a=0;a<5;a++){const d=[[0,0],[0,1],[1,0],[0,-1],[-1,0]][a],nx=x+d[0],ny=y+d[1];if(nx>=0&&ny>=0&&nx<data.rows&&ny<data.cols&&data.altitude[x][y]-data.altitude[nx][ny]>=data.threshold)good.push(['stay','up','right','down','left'][a]);}text+='; true safe actions: '+good.join(', ');}else{text+=' certified actions: '+f.certified_actions[s].map((v,a)=>v?['stay','up','right','down','left'][a]:null).filter(Boolean).join(', ');if(f.altitude_mean)text+=`; altitude GP ${f.altitude_mean[x][y].toFixed(4)} ± ${f.altitude_std[x][y].toFixed(4)}`;}
r.append(node('title',{},text));svg.append(r);if(!truth){for(let a=1;a<5;a++){if(f.certified_actions[s][a]){const dx=[0,0,1,0,-1][a]*10,dy=[0,-1,0,1,0][a]*10;svg.append(node('line',{x1:cx,y1:cy,x2:cx+dx,y2:cy+dy,stroke:'#30769d','stroke-width':1.8}));svg.append(node('circle',{cx:cx+dx,cy:cy+dy,r:1.7,fill:'#30769d'}));}}}}}
const points=frames.slice(0,index+1).map(v=>xy(...v.position).join(',')).join(' ');svg.append(node('polyline',{points,fill:'none',stroke:'#132f47','stroke-width':2}));const[cx,cy]=xy(...f.position);svg.append(node('circle',{cx,cy,r:5,fill:'#172e47',stroke:'white','stroke-width':1.5}));}
function chart(i){const svg=$('growth');svg.replaceChildren();const x=k=>40+700*k/Math.max(1,frames.length-1),y=v=>160-130*v,peak=Math.max(1,...frames.map(f=>f.discounted_return));for(const[key,scale,color]of[['discounted_return',peak,'#2c80b6'],['certified_cells',data.rows*data.cols,'#9353af']])svg.append(node('polyline',{points:frames.map((f,k)=>`${x(k)},${y(f[key]/scale)}`).join(' '),fill:'none',stroke:color,'stroke-width':2.5}));svg.append(node('line',{x1:x(i),x2:x(i),y1:20,y2:165,stroke:'#455e72','stroke-dasharray':'4 4'}));svg.append(node('text',{x:380,y:190,class:'label'},`Physical actions 0 to ${frames[frames.length-1].step}`));}
function render(){const i=Number(slider.value),f=frames[i];$('stepLabel').textContent=`Action ${f.step} / ${frames[frames.length-1].step}`;$('decision').textContent=`Phase: ${f.phase.replaceAll('_',' ')}. `+(f.stop_reason?`Stopped: ${f.stop_reason}.`:`Next: ${f.next_action}${f.target?`; target (${f.target.join(', ')})`:''}.`);$('metrics').replaceChildren();for(const[label,value]of[['Executable cells',f.certified_cells],['Certified actions',f.certified_action_count],['Expanders',f.expander_count],['Unsafe actions',f.unsafe_actions],['Incorrect actions',f.false_certified_actions]]){const d=document.createElement('div'),s=document.createElement('strong');s.textContent=value;d.append(s,document.createTextNode(label));$('metrics').append(d);}draw('belief',f,i,false);draw('truth',f,i,true);chart(i);$('diagnostic').textContent=f.diagnostic||'';$('previous').disabled=i===0;$('next').disabled=i===frames.length-1;}
function pause(){if(timer!==null)clearInterval(timer);timer=null;$('play').textContent='Play';}
slider.addEventListener('input',()=>{pause();render();});$('field').addEventListener('change',render);$('previous').addEventListener('click',()=>{pause();slider.value=Math.max(0,Number(slider.value)-1);render();});$('next').addEventListener('click',()=>{pause();slider.value=Math.min(frames.length-1,Number(slider.value)+1);render();});$('play').addEventListener('click',()=>{if(timer!==null){pause();return;}if(Number(slider.value)===frames.length-1)slider.value=0;$('play').textContent='Pause';render();timer=setInterval(()=>{if(Number(slider.value)>=frames.length-1){pause();return;}slider.value=Number(slider.value)+1;render();},300);});
$('scope').textContent=`${data.summary.method}; ${data.rows} × ${data.cols}; map source ${data.provenance.map_source}; upstream ${data.provenance.upstream_commit.slice(0,12)}. Coordinates are (x index, y index).`;$('outcome').textContent=`Discounted return ${data.summary.discounted_return.toFixed(4)}; unsafe actions ${data.summary.unsafe_actions}. Transition: ${data.summary.transition_reason||'none'} at ${data.summary.transition_step??'—'}. Altitude-difference threshold ${data.threshold}; grid spacing ${data.spacing}.`;render();
})().catch(error=>{document.getElementById('scope').textContent='Replay could not load: '+error.message;});
</script></body></html>"""
